import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.CzMjj32y.js";const k=JSON.parse('{"title":"Resolution & TAA","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Resolution & TAA | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"name":"twitter:title","content":"Resolution & TAA | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["link",{"rel":"canonical","href":"https://simonwarchol.github.io/kiln-render/rendering/resolution-taa.html"}],["meta",{"property":"og:url","content":"https://simonwarchol.github.io/kiln-render/rendering/resolution-taa.html"}]]},"headers":[],"relativePath":"rendering/resolution-taa.md","filePath":"rendering/resolution-taa.md"}'),n={name:"rendering/resolution-taa.md"};function r(l,e,h,o,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="resolution-taa" tabindex="-1">Resolution &amp; TAA <a class="header-anchor" href="#resolution-taa" aria-label="Permalink to &quot;Resolution &amp; TAA&quot;">​</a></h1><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>A settled view renders at full canvas resolution. While the camera moves (and for a short moment after), or while bricks are still streaming in, the viewer switches to <strong>draft frames</strong>: the compute shader renders at half resolution with a 2× ray step, and accumulation stops after 4 frames. A zoomed-in multichannel frame can cost hundreds of milliseconds of GPU time at full quality, and streaming keeps restarting accumulation anyway; once the view settles, rendering returns to full resolution.</p><p>The blit pass scales the compute output to the canvas (linear filtering). The depth texture stays at canvas size for geometry overlays (wireframe, axis). The render size is passed into the shader as <code>screenSize</code> so ray generation and thread dispatch use the correct coordinate space.</p><h2 id="temporal-jitter-and-accumulation" tabindex="-1">Temporal jitter and accumulation <a class="header-anchor" href="#temporal-jitter-and-accumulation" aria-label="Permalink to &quot;Temporal jitter and accumulation&quot;">​</a></h2><p>Raymarching with fixed step offsets produces banding artifacts where iso-surfaces align with sample planes. Kiln addresses this in two stages:</p><p><strong>Stochastic jitter</strong>: Each ray&#39;s starting offset is randomized per frame using the frame index as part of the seed:</p><div class="language-wgsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">wgsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jitter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rayToSeed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rayDir) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> brickIter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uniforms</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frameIndex);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jitter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stepSize;</span></span></code></pre></div><p>This converts structured banding into high-frequency noise that varies every frame.</p><p><strong>Temporal accumulation</strong>: A compute pass blends the current frame with a history buffer using an exponential moving average (EMA). Two ping-pong textures alternate as read and write targets to avoid read-write hazards:</p><div class="language-wgsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">wgsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> weight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (frameCount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Progressive average</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blended </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(history, current, weight);</span></span></code></pre></div><p>On frame 0, <code>weight = 1.0</code> shows the raw noisy frame. By frame 10, each pixel averages 11 samples, substantially reducing noise. A settled image accumulates 16 frames (draft frames 4); beyond that the returns diminish.</p><p>The accumulation resets automatically when:</p><ul><li>The camera moves (detected by comparing the view-projection matrix between frames)</li><li>Rendering parameters change (render mode, transfer function, window/level, ISO threshold)</li></ul><p>This gives immediate visual feedback during interaction, with progressive refinement when the view is still.</p>`,15)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
